int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long K;
    cin >> N >> K;

    vector<int> X(N);
    for (int &x : X) cin >> x;

    auto countAtMost = [&](long long limit) {
        if (limit < 0) return 0LL;

        long long count = 0;
        long long sum = 0;
        int left = 0;

        for (int right = 0; right < N; ++right) {
            sum += X[right];
            while (sum > limit) {
                sum -= X[left++];
            }
            count += right - left + 1;
        }

        return count;
    };

